const s=t=>`court-${t}`,n=t=>{const i=t.match(/^court-(\d+)$/);return i?parseInt(i[1],10):null},o=[{slug:"taipei",city:"台北市",shortName:"台北",intro:"台北市是全台匹克球密度最高的城市：從免費的青年公園、天母運動公園（17 面全台最大戶外群）、河濱球場，到運動中心時段與樓下、PicklePickle、花博 MAJI 等特色私人球館，各種預算與程度都找得到場地。多數場地捷運可達，晚上與週末熱門時段建議提早報名球敘或預約。"},{slug:"new-taipei",city:"新北市",shortName:"新北",intro:"新北市擁有全台首座河濱專用場「新北大都會公園匹克球中心」（8 面免費），加上 P.dang（淡水）、DOPE 水獺綠洲（新莊）、Pickle Day（中和）等指標球館，以及 2026 年起陸續開放匹克球租用的淡水、新店等國民運動中心，室內外選擇均衡。"},{slug:"keelung",city:"基隆市",shortName:"基隆",intro:"基隆的匹克球正在起步，目前以七堵堵南國小風雨球場的固定時段為主要據點。雨都球友也常跨區到雙北的室內館打球，期待更多場地加入。"},{slug:"taoyuan",city:"桃園市",shortName:"桃園",intro:"桃園的匹克球場以民營球館與運動中心為主：Social N Pickle 龜山（工業風專用場、線上預約）、龍潭 Loho 與中豐、蘆竹邷力豹，加上青埔、蘆竹運動中心與楊梅體育園區（室內 4 面）等場地時段穩定。科技業球友多、晚場需求旺，建議透過各館 LINE 或線上系統預約。"},{slug:"hsinchu",city:"新竹縣",shortName:"新竹",intro:"大新竹的匹克球場快速成長中：竹北星空匹克球場是大新竹首座公立專用場（免費），竹北國民運動中心有室內時段，寶山鄉則聚集了閃電匹克館 Inazuma 與 24 小時智能場 PPClub 兩間新球館，竹科球友下班就能開打。"},{slug:"hsinchu-city",city:"新竹市",shortName:"竹市",intro:"新竹市的匹克球以新竹市體育會匹克球委員會為推廣核心，西門國小是委員會的主要練習據點，三民國中則有課後與假日開放的戶外場。搭配竹縣的專用館，大新竹的球友選擇越來越多。"},{slug:"taichung",city:"台中市",shortName:"台中",intro:"台中的私人球館生態全台最成熟：PICKZONE 凱旋館與朝馬館提供 24 小時場地，西雅圖室內俱樂部早上 6 點開門，加上各運動中心時段，室內選擇豐富，雨季也不怕沒地方打。"},{slug:"changhua",city:"彰化縣",shortName:"彰化",intro:"彰化是中部匹克球推廣最積極的縣市之一：大村有彰化首座室內標準場，秀水、延平公園有免費戶外場，2026 年 7 月社頭 OH9 黑狗兄綜合球館加入戰場，市長盃等基層賽事也逐年擴大。"},{slug:"nantou",city:"南投縣",shortName:"南投",intro:"南投的匹克球場以共用場地為主，埔里地理中心碑的羽匹共用場是當地球友的主要據點。想打專用場的球友可搭配鄰近的台中、彰化場地安排。"},{slug:"yunlin",city:"雲林縣",shortName:"雲林",intro:"雲林迎來突破：2026 年虎尾交流道旁開幕的 PK Park 是雲林第一座匹克球專用館（4 面標準場、營業到午夜），加上雲科大的免費校園場地，雲林球友終於不用再跨縣打球。"},{slug:"chiayi",city:"嘉義市",shortName:"嘉義",intro:"嘉義市的據點越來越完整：嘉義市國民運動中心（東區彌陀路）有室內時段，西區帝寶球場午後開放，加上嘉義高工校園場地。雲嘉地區球友的主要聚集地。"},{slug:"chiayi-county",city:"嘉義縣",shortName:"嘉縣",intro:"嘉義縣以水上鄉全民運動館為室內主場，朴子縣政府田徑場則有免費開放時段。與嘉義市的場地互相支援，嘉南平原的匹克球版圖持續擴大。"},{slug:"tainan",city:"台南市",shortName:"台南",intro:"台南的匹克球場以運動中心與學校場地為主，戶外場受天候影響小、全年可打。南部球友社群活躍，跨區到高雄參賽交流也很方便。"},{slug:"kaohsiung",city:"高雄市",shortName:"高雄",intro:"高雄是南台灣匹克球重鎮：中華民國匹克球總會（CTPF）即以高雄為基地，港都盃全國錦標賽每年在樹德科大開打。2026 年 6 月啟用的楠仔坑運動中心綜合球場（300 席看台）讓高雄多了可辦賽事的新場館。"},{slug:"pingtung",city:"屏東縣",shortName:"屏東",intro:"屏東以國立屏東大學為推廣核心，國民體育日系列活動與縣級邀請賽都在此舉行，2027 年臺灣盃也預定移師屏東。校園與公共場地是主要選擇。"},{slug:"yilan",city:"宜蘭縣",shortName:"宜蘭",intro:"宜蘭運動公園擁有 8 面戶外場並多次承辦全國賽事（臺灣盃、噶瑪蘭盃），縣府並規劃於 2026 年底完工至少 6 面的風雨多元球場。東部球友的主場，也適合安排運動小旅行。"},{slug:"hualien",city:"花蓮縣",shortName:"花蓮",intro:"花蓮迎來第一座室內館：吉安鄉 PKing 匹克俱樂部（08:00-22:00），加上花蓮市中山公園的戶外場。東部球友社群規模較小但凝聚力強，建議透過 LINE 社群確認球敘時段。"}],a=t=>o.find(i=>i.slug===t),r=t=>o.find(i=>i.city===t);export{o as C,a,s as c,r as g,n as p};
